mapper.select:
SELECT fd.id, fdd.id as detailId, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.packing_status AS packingStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdl.logistics_method AS logisticsMethod, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, op.code as provideCode, fdd.platform_sku_no as thirdWarehouseSku, fd.logistics_status, fd.declare_status FROM first_mile_delivery_detail fdd LEFT JOIN first_mile_delivery fd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN first_mile_delivery_logistics fdl ON fd.id = fdl.main_id AND fdl.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = fd.dest_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.id, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.packing_status AS packingStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdl.logistics_method AS logisticsMethod, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, op.code as provideCode FROM first_mile_delivery fd INNER JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN first_mile_delivery_logistics fdl ON fd.id = fdl.main_id AND fdl.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = fd.dest_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fmd.id, fmd.packing_status, fmd.code, fmcb.box_no, concat(box_length, '*', fmc.box_width, '*', fmc.box_height) AS boxSize, fmc.package_weight, fmcb.box_desc FROM first_mile_delivery fmd LEFT JOIN first_mile_carton fmc ON fmc.source_id = fmd.id AND fmc.is_deleted = FALSE LEFT JOIN first_mile_carton_bill fmcb ON fmc.id = fmcb.carton_id AND fmcb.is_deleted = FALSE WHERE ${params.sqlMap.default} and fmd.is_deleted = FALSE
${params.permissionSql}
ORDER BY fmd.code, CAST(fmcb.box_no AS INTEGER)
